"""Lunch order — generated by lowcode.generator from forms/lunch-order.json. Do not edit."""

from __future__ import annotations

import sys
from collections.abc import Sequence
from datetime import datetime
from typing import Any

from lowcode.app import FormApp
from lowcode.app import main as _run_cli
from lowcode.schema import FormSpec

SPEC = FormSpec.from_dict(
    {
        "cutoff": {
            "time": "10:00",
            "weekday": "friday"
        },
        "fields": [
            {
                "choices": [
                    "falafel wrap",
                    "chicken curry",
                    "veggie pizza",
                    "salad bowl"
                ],
                "name": "dish",
                "required": True,
                "type": "choice"
            },
            {
                "maximum": 5,
                "minimum": 1,
                "name": "quantity",
                "required": True,
                "type": "number"
            },
            {
                "max_length": 40,
                "name": "team",
                "required": True,
                "type": "text"
            },
            {
                "max_length": 120,
                "name": "notes",
                "required": False,
                "type": "text"
            }
        ],
        "slug": "lunch_order",
        "title": "Lunch order"
    }
)

APP = FormApp(SPEC)


def submit(values: dict[str, Any], *, now: datetime | None = None) -> dict[str, Any]:
    """Submit one lunch_order form (validated against SPEC, subject to the cut-off)."""
    return APP.submit(values, now=now)


def rows() -> list[dict[str, Any]]:
    """Every submission stored in this process."""
    return APP.rows()


def export_csv() -> str:
    """The table as CSV text."""
    return APP.export_csv()


def main(argv: Sequence[str] | None = None) -> int:
    """Command line: submit, list, export (persisted in a JSON store)."""
    return _run_cli(SPEC, argv)


if __name__ == "__main__":
    sys.exit(main())
